INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Programmierwerkzeuge immer auf IDEs beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Umfassen auch Compiler, Debugger"}, {"text": "Ja", "correct": false, "because": "Vielfältige Werkzeuge"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel von Programmierwerkzeugen?', 3, '[{"text": "Effiziente Entwicklung", "correct": true, "because": "Vereinfachen Coding"}, {"text": "Grafische Animationen", "correct": false, "because": "Nicht primär"}, {"text": "Manuelle Codierung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Programmierwerkzeugen gibt es?', 5, '[{"text": "Texteditoren", "correct": true, "because": "Zum Schreiben von Code"}, {"text": "Debugger", "correct": true, "because": "Finden Fehler"}, {"text": "Bildbearbeitung", "correct": false, "because": "Nicht entwicklungsspezifisch"}, {"text": "Musikwiedergabe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) IDEs integrieren mehrere Werkzeuge. b) Programmierwerkzeuge sind immer kostenpflichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) gibt kostenlose Tools"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl von Programmierwerkzeugen?', 4, '[{"text": "Kompatibilität", "correct": false, "because": "Sichert Integration"}, {"text": "Benutzerfreundlichkeit", "correct": false, "because": "Erleichtert Arbeit"}, {"text": "Farbcodierung", "correct": true, "because": "Sekundär relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Compiler ein Programmierwerkzeug ist?', 2, '[{"text": "Ja", "correct": true, "because": "Übersetzt Code"}, {"text": "Nein", "correct": false, "because": "Kernwerkzeug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft beim Finden von Fehlern?', 3, '[{"text": "Debugger", "correct": true, "because": "Analysiert Codeausführung"}, {"text": "Texteditor", "correct": false, "because": "Nur zum Schreiben"}, {"text": "Manuelle Prüfung", "correct": false, "because": "Debugger effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Programmierwerkzeuge?', 5, '[{"text": "Fehlerreduktion", "correct": true, "because": "Debugger, Linter helfen"}, {"text": "Produktivität", "correct": true, "because": "Automatisieren Aufgaben"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher Nachteil"}, {"text": "Manuelle Codierung", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Git ist ein Versionskontrolltool. b) Alle Werkzeuge sind cloudbasiert. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch lokal möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Programmierwerkzeuge?', 4, '[{"text": "Code-Editor", "correct": false, "because": "Zum Schreiben nötig"}, {"text": "Compiler", "correct": false, "because": "Übersetzt Code"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein Programmierbedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind alle IDEs kostenpflichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Kostenlose wie VS Code existieren"}, {"text": "Ja", "correct": false, "because": "Viele sind kostenlos"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge unterstützen Teamarbeit?', 4, '[{"text": "Git", "correct": true, "because": "Versionskontrolle"}, {"text": "Jira", "correct": true, "because": "Projektmanagement"}, {"text": "3D-Modellierung", "correct": false, "because": "Nicht entwicklungsspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Programmierwerkzeuge immer komplex sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Viele sind benutzerfreundlich"}, {"text": "Ja", "correct": false, "because": "Komplexität variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl von Programmierwerkzeugen?', 3, '[{"text": "Projektanforderungen", "correct": true, "because": "Sichert Passung"}, {"text": "Maximale Features", "correct": false, "because": "Einfachheit oft besser"}, {"text": "Manuelle Installation", "correct": false, "because": "Automatisierung effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) VS Code ist ein Texteditor. b) Alle Werkzeuge benötigen Internet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch offline möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktionen bieten IDEs?', 5, '[{"text": "Code-Vervollständigung", "correct": true, "because": "Erleichtert Coding"}, {"text": "Debugging", "correct": true, "because": "Findet Fehler"}, {"text": "Musikwiedergabe", "correct": false, "because": "Nicht entwicklungsspezifisch"}, {"text": "Bildbearbeitung", "correct": false, "because": "Andere Domäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Programmierwerkzeugen unwichtig?', 3, '[{"text": "Leistung", "correct": false, "because": "Beeinflusst Effizienz"}, {"text": "Kompatibilität", "correct": false, "because": "Sichert Integration"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Entwicklungsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Linter ein Programmierwerkzeug ist?', 2, '[{"text": "Ja", "correct": true, "because": "Prüft Codequalität"}, {"text": "Nein", "correct": false, "because": "Teil der Toolchain"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Programmierwerkzeuge nur für Profis?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für Anfänger geeignet"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Programmierwerkzeugen?', 4, '[{"text": "Entwicklung einer App", "correct": true, "because": "Nutzt IDEs, Debugger"}, {"text": "Musikwiedergabe", "correct": false, "because": "Andere Domäne"}, {"text": "Netzwerkwartung", "correct": false, "because": "Technische Aufgabe"}]');
